func summaryRanges(nums []int) []string {
	ans := []string{}
	for i := 0; i < len(nums); i++ {
		start := nums[i]
		for i+1 < len(nums) && nums[i+1] == nums[i]+1 {
			i++
		}
		if nums[i] == start {
			ans = append(ans, strconv.Itoa(start))
		} else {
			ans = append(ans, fmt.Sprintf("%d->%d", start, nums[i]))
		}
	}
	return ans
}
